        "평가사유": "[화제성 7점] (확정 →) 모네·르누아르·반 고흐·세잔을 앞세운 인상주의 거장 라인업이 국립아시아문화전당 공식 전시 페이지로 확인되고, 개막 6주 전인 2026-08-10(카카오)·08-13(티켓링크·네이버·NOL)에 얼리버드 예매를 여는 유료 대형 기획전이다. 인상파는 국내에서 반복 검증된 관객 동원 소재다. (추정 →) 다만 실제 매진·동원 지표는 아직 없고 광주 소재라 전국민 단위 화제로 보긴 어려워 8점 이상 근거는 부족하다.\n[독창성 4점] (독점성·희소성·차별 기획 관점) 거장 진품을 모으는 희소 기획이라는 점은 인정되나, 누구나 표를 사서 볼 수 있는 공개 유료 전시이고 우리 매체의 독점 취재권·독점 콘텐츠 권리가 없다. 실무자 원칙1(공개 전시로 독점 확보 불가 시 독창성 하단)을 적용해 4점으로 제한한다. 프리즈 서울 2026(독창성 4점)과 같은 수준으로 본다.\n[근접성 5점] (지방·기간 관점) 2026-09-23~2027-02-21로 약 5개월 장기 편성이라 관람 기회는 넉넉하다. 그러나 장소가 광주 국립아시아문화전당으로 수도권이 아니어서 물리적 접근성이 크게 깎인다. 장기 편성(+)과 지방 소재(−)를 상쇄해 5점으로 본다.\n[영향성 7점] (추정 →) 5개월 장기 유료 대형전이라 관람 규모와 미디어 노출이 크고, 인상주의는 우리 매거진이 지속적으로 다뤄온 전시 주제여서 채널 신뢰도 제고에 기여한다(실무자 원칙4: 매거진이 다뤄온 주제는 영향성 가점). 서도호 개인전 영향성 8점보다는 한 단계 아래로 둔다.\n[종합] 강점: 거장 진품 라인업 + 5개월 장기 + 이미 시작된 얼리버드 예매. 약점·리스크: 광주 소재로 수도권 시청자의 실제 관람 전환이 낮고, 독점 취재 여지가 없어 타 매체와 차별이 어렵다. 편성 관점: 장기 편성이라 방송 시점을 자유롭게 잡을 수 있고 인상주의 기획과 묶기 좋다.",
