        "저자역자": "저자 : 김금숙",
        "장르형태": "그래픽노블(역사·여순사건)",
        "출판사": "(주식회사)창비",
        "평가사유": "[화제성 6점] (확정 →) 김금숙은 『풀』로 하비상을 받았고 한국 만화가 최초로 프랑스 문화예술공로훈장(슈발리에)을 받은 작가다. 경인일보 인터뷰에서 신작 화두가 고향의 '여순사건'임을 직접 밝혔고, 창비에서 2026년 10월 출간이 확인된다. (추정 →) 예약 단계라 판매지수는 0.\n[독창성 7점] 여순사건을 정면으로 다룬 그래픽노블은 사실상 유일하고, 작가가 여수 출신이라는 개인사가 겹친다. 작가 인터뷰·작업실 취재 등 독점 각도가 명확하다. 이번 회차에서 독창성이 가장 높다.\n[근접성 7점] 여순사건은 국가 차원의 진상규명이 진행 중인 현재진행형 의제이고, 만화라는 형식 덕분에 진입 장벽이 낮다.\n[영향성 7점] 역사 의제화 + 국제 수상 이력에 따른 해외 전개 가능성 + 다큐 연계 여지까지 있어 파급이 가장 넓다.\n[종합] 강점: 국제적으로 검증된 작가 + 유일무이한 소재 + 독점 인터뷰 확보 가능성. 약점·리스크: 10-19 출간이라 이번 회차에는 선(先) 예고 성격, 근현대사 사건이라 정치적 해석 부담. 편성: **이번 회차 최우선 추천.** 작가 단독 인터뷰를 지금 확보할 것.",
